// Public local development accounts are generated by Hardhat. Never print its account/key banner.
import {spawn} from 'node:child_process';
const child=spawn(process.execPath,['node_modules/hardhat/dist/src/cli.js','node','--hostname','127.0.0.1','--port','8545'],{stdio:['ignore','pipe','pipe']});
let ready=false;
child.stdout.on('data',data=>{const text=data.toString();if(!ready&&text.includes('8545')){ready=true;console.log('Local development EVM listening on 127.0.0.1:8545, chain 31337. Public disposable development accounts only.');}});
child.stderr.on('data',data=>{const message=data.toString();if(!/Private Key|0x[0-9a-f]{64}/i.test(message))process.stderr.write(message);});
process.on('SIGINT',()=>child.kill());process.on('SIGTERM',()=>child.kill());
child.on('exit',code=>process.exit(code||0));
